    print(c['customerNo'], c['firstName'], c['lastName'], 'list http', cl.get('http'), cl.get('delaySeconds',''), [(k['cardNumberLast4'],k['productName'],k.get('isMainCard')) for k in cards] if isinstance(cards,list) else str(cards)[:300])
